/* gui_button(x, y, w, h, text): ????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????	????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????, ???????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????? id */
static int builtin_gui_button(VM *vm) {
    int argc = vm_cur_sp(vm) + 1;
    if (!G.stageCreated) { popn(vm, vm_cur_sp(vm) + 1); push_int(vm, -1); return 1; }
    int x = (int)arg_num(vm, argc - 1), y = (int)arg_num(vm, argc - 2);
    int w = (int)arg_num(vm, argc - 3), h = (int)arg_num(vm, argc - 4);
    char txt[256] = ""; if (argc >= 5) snprintf(txt, sizeof txt, "%s", arg_str(vm, argc - 5));
    int st = 0; if (argc >= 6) st = (int)arg_num(vm, argc - 6);
    popn(vm, vm_cur_sp(vm) + 1);
    int id = -1;
    EnterCriticalSection(&G.lock);
    if (G.ctrlCount < MAX_CTRLS) {
        GuiCtrl *c = &G.ctrls[G.ctrlCount];
        memset(c, 0, sizeof *c);
        c->type = CTRL_BUTTON; c->x = x; c->y = y; c->w = w; c->h = h;
        c->visible = 1; c->style = st ? 1 : 0;
        snprintf(c->text, sizeof c->text, "%s", txt);
        id = ++G.ctrlCount;
    }
    LeaveCriticalSection(&G.lock);
    push_int(vm, id); return 1;
}
/* gui_button_clicked(id): 	????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????/&???????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????? (????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????v????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????) */
static int builtin_gui_button_clicked(VM *vm) {
    int argc = vm_cur_sp(vm) + 1;
    int id = (int)arg_num(vm, argc - 1);
    popn(vm, vm_cur_sp(vm) + 1);
    int r = 0;
    EnterCriticalSection(&G.lock);
    if (id >= 1 && id <= G.ctrlCount && G.ctrls[id - 1].type == CTRL_BUTTON && G.ctrls[id - 1].clicked) {
        r = 1; G.ctrls[id - 1].clicked = 0;
    }
    LeaveCriticalSection(&G.lock);
    push_int(vm, r); return 1;
}
