static void shape_add(int type, int x, int y, int w, int h, int color, int fg, int titleColor, const char *text, int align) {
    if (G.pendshCount >= MAX_TEXTS) G.pendshCount = 0;
    GuiShape *sh = &G.pendsh[G.pendshCount++];
    sh->type = type; sh->x = x; sh->y = y; sh->w = w; sh->h = h;
    sh->color = color; sh->fg = fg; sh->titleColor = titleColor;
    snprintf(sh->text, sizeof(sh->text), "%s", text ? text : "");
    sh->align = align;
}
