static int builtin_gui_touch(VM *vm) {
    int argc = vm_cur_sp(vm) + 1;
    GuiSprite *a = find_sprite(bound_sprite(vm));
    GuiSprite *b = (argc >= 1) ? find_sprite(arg_str(vm, 0)) : NULL;
    int hit = 0;
    if (a && b) {
        int aw = a->boxSet ? a->boxW : a->bmW, ah = a->boxSet ? a->boxH : a->bmH;
        int bw = b->boxSet ? b->boxW : b->bmW, bh = b->boxSet ? b->boxH : b->bmH;
        int ax1 = (int)(a->x - a->bmW / 2.0) + (a->boxSet ? a->boxX : 0);
        int ay1 = (int)(a->y - a->bmH / 2.0) + (a->boxSet ? a->boxY : 0);
        int bx1 = (int)(b->x - b->bmW / 2.0) + (b->boxSet ? b->boxX : 0);
        int by1 = (int)(b->y - b->bmH / 2.0) + (b->boxSet ? b->boxY : 0);
        hit = (ax1 < bx1 + bw && bx1 < ax1 + aw && ay1 < by1 + bh && by1 < ay1 + ah);
        if (hit && ((a->flags & 0x2) || (b->flags & 0x2))) hit = 0; /* ghost skips collision */
    }
    LeaveCriticalSection(&G.lock);
    popn(vm, argc);
    push_int(vm, hit); return 1;
}
