/* ================= Inimerse2D engine (P0) ================= */
static double im2d_cam_x = 0, im2d_cam_y = 0, im2d_cam_zoom = 1;

static int builtin_im2d_init(VM *vm) {
    int argc = vm_cur_sp(vm) + 1;
    int ms = (int)arg_num(vm, 0);
    if (ms <= 0) ms = 16;
    vm->im2d_interval_ms = ms;
    vm->im2d_next_frame = 0;
    vm->im2d_ready = 0;
    vm->im2d_scene[0] = 0;
    vm->im2d_last_scene[0] = 0;
    popn(vm, argc);
    ret(vm, 1);
    return 1;
}
static int builtin_im2d_camera(VM *vm) {
    int argc = vm_cur_sp(vm) + 1;
    im2d_cam_x = arg_num(vm, 0);
    im2d_cam_y = arg_num(vm, 1);
    im2d_cam_zoom = (argc >= 3) ? arg_num(vm, 2) : 1.0;
    if (im2d_cam_zoom <= 0) im2d_cam_zoom = 1;
    popn(vm, argc);
    ret(vm, 1);
    return 1;
}
static int builtin_im2d_goto_scene(VM *vm) {
    int argc = vm_cur_sp(vm) + 1;
    const char *s = arg_str(vm, 0);
    if (s) snprintf(vm->im2d_scene, sizeof(vm->im2d_scene), "%s", s);
    popn(vm, argc);
    ret(vm, 1);
    return 1;
}
static int builtin_im2d_dt(VM *vm) {
    if (vm_cur_sp(vm) >= 0) popn(vm, vm_cur_sp(vm) + 1);
    push_float(vm, (float)vm->im2d_dt);
    return 1;
}
static int builtin_im2d_cam_x_fn(VM *vm) {
    if (vm_cur_sp(vm) >= 0) popn(vm, vm_cur_sp(vm) + 1);
    push_float(vm, (float)im2d_cam_x);
    return 1;
}
static int builtin_im2d_cam_y_fn(VM *vm) {
    if (vm_cur_sp(vm) >= 0) popn(vm, vm_cur_sp(vm) + 1);
    push_float(vm, (float)im2d_cam_y);
    return 1;
}
static int builtin_im2d_cam_zoom_fn(VM *vm) {
    if (vm_cur_sp(vm) >= 0) popn(vm, vm_cur_sp(vm) + 1);
    push_float(vm, (float)im2d_cam_zoom);
    return 1;
}
static int builtin_im2d_world_to_screen(VM *vm) {
    int argc = vm_cur_sp(vm) + 1;
    double wx = arg_num(vm, 0), wy = arg_num(vm, 1);
    popn(vm, argc);
    int cw = G.W ? G.W : 800, ch = G.H ? G.H : 600;
    double sx = (wx - im2d_cam_x) * im2d_cam_zoom + cw / 2.0;
    double sy = (wy - im2d_cam_y) * im2d_cam_zoom + ch / 2.0;
    int aidx = vm_array_new(vm);
    if (aidx < 0) { ret(vm, 0); return 1; }
    { Value v; v.type = VAL_FLOAT; v.fval = sx; v.ival = 0; v.sval = NULL;
      vm_array_push(vm, aidx, &v); v.fval = sy; vm_array_push(vm, aidx, &v); }
    Value arrv; arrv.type = VAL_ARRAY; arrv.ival = aidx + 1; arrv.fval = 0; arrv.sval = NULL;
    if (vm_cur_sp(vm) < 1023) { vm_cur_set_sp(vm, vm_cur_sp(vm) + 1); vm_cur_stack(vm)[vm_cur_sp(vm)] = arrv; }
    else ret(vm, 0);
    return 1;
}
static int builtin_im2d_draw_sprite(VM *vm) {
    int argc = vm_cur_sp(vm) + 1;
    char name[64] = ""; snprintf(name, sizeof name, "%s", arg_str(vm, 0));
    double wx = arg_num(vm, 1), wy = arg_num(vm, 2);
    popn(vm, argc);
    create_stage(G.W ? G.W : 800, G.H ? G.H : 600);
    EnterCriticalSection(&G.lock);
    GuiSprite *sp = find_sprite(name);
    if (sp) {
        int cw = G.W ? G.W : 800, ch = G.H ? G.H : 600;
        sp->x = (wx - im2d_cam_x) * im2d_cam_zoom + cw / 2.0;
        sp->y = (wy - im2d_cam_y) * im2d_cam_zoom + ch / 2.0;
        if (im2d_cam_zoom != 1.0 && sp->size > 0) sp->size = (int)(sp->size * im2d_cam_zoom);
    }
    LeaveCriticalSection(&G.lock);
    ret(vm, 1);
    return 1;
}
static int builtin_im2d_draw_rect(VM *vm) {
    int argc = vm_cur_sp(vm) + 1;
    double wx = arg_num(vm, 0), wy = arg_num(vm, 1);
    double ww = arg_num(vm, 2), wh = arg_num(vm, 3);
    int color = (int)arg_num(vm, 4);
    popn(vm, argc);
    create_stage(G.W ? G.W : 800, G.H ? G.H : 600);
    int cw = G.W ? G.W : 800, ch = G.H ? G.H : 600;
    int sx = (int)((wx - im2d_cam_x) * im2d_cam_zoom + cw / 2.0);
    int sy = (int)((wy - im2d_cam_y) * im2d_cam_zoom + ch / 2.0);
    int sw = (int)(ww * im2d_cam_zoom), sh = (int)(wh * im2d_cam_zoom);
    EnterCriticalSection(&G.lock);
    shape_add(0, sx, sy, sw, sh, color, 0, 0, "", 0);
    LeaveCriticalSection(&G.lock);
    ret(vm, 1);
    return 1;
}


