static int builtin_noise2d(VM *vm) { /* noise2d(x,y,seed) -> [0,1] value noise */
    int argc = vm->cur_argc > 0 ? vm->cur_argc : vm_cur_sp(vm) + 1;
    int seed = (int)arg_num(vm, argc - 3);
    double y = arg_num(vm, argc - 2);
    double x = arg_num(vm, argc - 1);
    popn(vm, argc);
    int x0 = (int)floor(x), y0 = (int)floor(y);
    double fx = x - (double)x0, fy = y - (double)y0;
    double sx = noise_smooth(fx), sy = noise_smooth(fy);
    double n00 = (double)(noise_hash2(x0, y0, seed) & 0xFFFF) / 65535.0;
    double n10 = (double)(noise_hash2(x0 + 1, y0, seed) & 0xFFFF) / 65535.0;
    double n01 = (double)(noise_hash2(x0, y0 + 1, seed) & 0xFFFF) / 65535.0;
    double n11 = (double)(noise_hash2(x0 + 1, y0 + 1, seed) & 0xFFFF) / 65535.0;
    double v = n00 * (1 - sx) * (1 - sy) + n10 * sx * (1 - sy) + n01 * (1 - sx) * sy + n11 * sx * sy;
    push_double(vm, v);
    return 1;
}

static int builtin_gui_frame_interval(VM *vm) { /* gui_frame_interval(ms): steady-state stream interval (default 16) */
    int argc = vm_cur_sp(vm) + 1;
    double ms = arg_num(vm, argc - 1);
    popn(vm, argc);
    if (ms >= 4 && ms <= 5000) g_stream_iv = (int)ms;
    ret(vm, 1); return 1;
}

