/* ================= headless frame stream ================= */
/* headless: append control widgets (input/button/log) into frame r-array */

static void hl_escape(const char *src, int len, char *hbuf, int *hp, int cap) {
    wchar_t wbuf[512];
    int wlen = MultiByteToWideChar(CP_UTF8, 0, src, len, wbuf, 512);
    if (wlen <= 0) return;
    int outChars = (len < 0) ? wlen - 1 : wlen;
    char ubuf[1024];
    int ulen = WideCharToMultiByte(CP_UTF8, 0, wbuf, outChars, ubuf, 1024, NULL, NULL);
    for (int ui = 0; ui < ulen && *hp < cap - 1; ui++) {
        unsigned char c = (unsigned char)ubuf[ui];
        if (c == '"' || c == '\\') {
            if (*hp + 2 >= cap) break;
            hbuf[(*hp)++] = '\\';
            hbuf[(*hp)++] = (char)c;
        } else if (c == '\b' || c == '\f' || c == '\n' || c == '\r' || c == '\t') {
            if (*hp + 2 >= cap) break;
            hbuf[(*hp)++] = '\\';
            hbuf[(*hp)++] = (c == '\b') ? 'b' : (c == '\f') ? 'f' : (c == '\n') ? 'n' : (c == '\r') ? 'r' : 't';
        } else if (c < 0x20) {
            if (*hp + 6 >= cap) break;
            *hp += snprintf(hbuf + *hp, (size_t)(cap - *hp), "\\u%04x", (unsigned)c);
        } else {
            hbuf[(*hp)++] = (char)c;
        }
    }
}
static void gui_headless_stream(void) {
    char hbuf[65536]; int hp = 0;
    hl_appendf(hbuf, &hp, (int)sizeof hbuf, "{\"f\":%d,\"w\":%d,\"h\":%d,\"t\":[", hl_frameNo, G.W, G.H);
    for (int di = 0; di < G.textCount && hp < (int)sizeof hbuf - 1024; di++) {
        if (di) hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",");
        hl_appendf(hbuf, &hp, (int)sizeof hbuf, "{\"x\":%d,\"y\":%d,\"s\":\"", G.texts[di].x, G.texts[di].y);
        /* text is UTF-8 already: pass through with JSON escaping (identity) */
        {
            wchar_t wbuf[512];
            int wlen = MultiByteToWideChar(CP_UTF8, 0, G.texts[di].text, -1, wbuf, 512);

            if (wlen > 0) {
                char ubuf[1024];
                int ulen = WideCharToMultiByte(CP_UTF8, 0, wbuf, wlen - 1, ubuf, 1024, NULL, NULL);
                hl_escape(ubuf, ulen, hbuf, &hp, (int)sizeof hbuf);
            }
            hl_appendf(hbuf, &hp, (int)sizeof hbuf, "\"}");
        }
    }
    hl_appendf(hbuf, &hp, (int)sizeof hbuf, "],\"r\":[");
    for (int si = 0; si < G.shapeCount && hp < (int)sizeof hbuf - 512; si++) {
        GuiShape *sh = &G.shapes[si];
        if (si) hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",");
        hl_appendf(hbuf, &hp, (int)sizeof hbuf, "{\"t\":%d,\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":%u,\"s\":\"", sh->type, sh->x, sh->y, sh->w, sh->h, (unsigned)sh->color);
        {
            wchar_t wbuf[512];
            int wlen = MultiByteToWideChar(CP_UTF8, 0, sh->text, -1, wbuf, 512);
            if (wlen > 0) {
                char ubuf[1024];
                int ulen = WideCharToMultiByte(CP_UTF8, 0, wbuf, wlen - 1, ubuf, 1024, NULL, NULL);
                hl_escape(ubuf, ulen, hbuf, &hp, (int)sizeof hbuf);
            }
            hl_appendf(hbuf, &hp, (int)sizeof hbuf, "\"}");
        }
    }
    /* ---- controls as shapes (input / button / log) ---- */
    for (int ci = 0; ci < G.ctrlCount && hp < (int)sizeof hbuf - 4096; ci++) {
        GuiCtrl *c = &G.ctrls[ci];
        if (!c->visible) continue;
        int cx = c->rel ? (c->x * G.W) / 1000 : c->x;
        int cy = c->rel ? (c->y * G.H) / 1000 : c->y;
        int cw = c->rel ? (c->w * G.W) / 1000 : c->w;
        int ch = c->rel ? (c->h * G.H) / 1000 : c->h;
        if (c->type == CTRL_INPUT) {
            hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",{\"t\":0,\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":%u,\"s\":\"\"}", cx, cy, cw, ch, (unsigned)0xFFFFFF);
            hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",{\"t\":1,\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":%u,\"s\":\"\"}", cx, cy, cw, ch, (unsigned)(c->focused ? 0x000000 : 0x9A9A9A));
            if (c->text[0]) {
                hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",{\"t\":4,\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":%u,\"s\":\"", cx + 6, cy + 4, cw - 12, 26, (unsigned)0x101010);
                hl_escape(c->text, -1, hbuf, &hp, (int)sizeof hbuf);
                hl_appendf(hbuf, &hp, (int)sizeof hbuf, "\"}");
            }
        } else if (c->type == CTRL_BUTTON) {
            if (c->style == 1) {
                hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",{\"t\":0,\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":%u,\"s\":\"\"}", cx, cy, cw, ch, (unsigned)0xE6F0FA);
                hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",{\"t\":1,\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":%u,\"s\":\"\"}", cx, cy, cw, ch, (unsigned)0x3C5A8C);
            }
            if (c->text[0]) {
                hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",{\"t\":4,\"a\":1,\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":%u,\"s\":\"", cx, cy + 4, cw, 26, (unsigned)(c->style == 1 ? 0x283C5A : 0xDDDDDD));
                hl_escape(c->text, -1, hbuf, &hp, (int)sizeof hbuf);
                hl_appendf(hbuf, &hp, (int)sizeof hbuf, "\"}");
            }
        } else if (c->type == CTRL_LOG) {
            hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",{\"t\":0,\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":%u,\"s\":\"\"}", cx, cy, cw, ch, (unsigned)0x141D2C);
            int maxRows = (ch - 8) / 22; if (maxRows < 1) maxRows = 1;
            const char *p = c->text; int line = 0;
            while (*p && line < c->scroll + maxRows + 1 && hp < (int)sizeof hbuf - 2048) {
                const char *e = strchr(p, '\n');
                int len = e ? (int)(e - p) : (int)strlen(p);
                if (line >= c->scroll && line < c->scroll + maxRows && len > 0) {
                    hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",{\"t\":4,\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":%u,\"s\":\"", cx + 6, cy + 6 + (line - c->scroll) * 22, cw - 12, 20, (unsigned)0xD8E0EA);
                    hl_escape(p, len, hbuf, &hp, (int)sizeof hbuf);
                    hl_appendf(hbuf, &hp, (int)sizeof hbuf, "\"}");
                }
                if (!e) break;
                p = e + 1; line++;
            }
        }
    }
    /* P1: sprite metadata for hot-join clients (asset by costume path) */
    hl_appendf(hbuf, &hp, (int)sizeof hbuf, "],\"sp\":[");
    int spFirst = 1;
    for (int si = 0; si < G.spriteCount && hp < (int)sizeof hbuf - 8192; si++) { 
        GuiSprite *sp = &G.sprites[si];
        if (!sp->alive || !sp->visible || !sp->bm) continue;
        if (!spFirst) hl_appendf(hbuf, &hp, (int)sizeof hbuf, ",");
        spFirst = 0;
        hl_appendf(hbuf, &hp, (int)sizeof hbuf, "{\"n\":\"");
        hl_escape(sp->name, -1, hbuf, &hp, (int)sizeof hbuf);
        hl_appendf(hbuf, &hp, (int)sizeof hbuf, "\",\"x\":%d,\"y\":%d,\"w\":%d,\"h\":%d,\"c\":\"",
                    (int)sp->x, (int)sp->y, sp->bmW * sp->size / 100, sp->bmH * sp->size / 100);
        hl_escape(sp->costumeCount > 0 ? sp->costumes[sp->currentCostume] : "", -1, hbuf, &hp, (int)sizeof hbuf);
        hl_appendf(hbuf, &hp, (int)sizeof hbuf, "\"}");
    }
hl_appendf(hbuf, &hp, (int)sizeof hbuf, "]}");
    /* Keep the wire format valid even when user-controlled content fills the
     * bounded frame buffer: send a compact empty frame instead of truncation. */
    if (hp >= (int)sizeof hbuf - 1) {
        hp = snprintf(hbuf, sizeof hbuf,
                      "{\"f\":%d,\"w\":%d,\"h\":%d,\"t\":[],\"r\":[],\"sp\":[]}",
                      hl_frameNo, G.W, G.H);
    }
    headless_send_frame(hbuf);
}

#pragma GCC diagnostic pop

